begin;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.reject(query text,code text default null) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute query;exception when others then if code is not null and SQLSTATE<>code then raise;end if;blocked:=true;end;if not blocked then raise exception 'Unauthorized/invalid operation succeeded: %',query;end if;end$$;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.session',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '2 hours',now()-interval '1 hour','Atomic checkout')::text,true);
select pg_temp.reject($q$select public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003',now(),now()+interval '1 hour','Wrong teacher')$q$);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000003';
select pg_temp.assert_true((select count(*)=0 from public.class_sessions),'Teacher B cannot read A');
select pg_temp.reject('select public.start_class_session('''||current_setting('p2.session')||''')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.session')::uuid);
select pg_temp.assert_true((select count(*)=5 from public.session_student_records),'Roster snapshot');
select set_config('p2.data',(select jsonb_build_object('lesson_content','Lesson','homework_assigned','Practice','records',jsonb_agg(jsonb_build_object('student_id',student_id,'attendance',case when student_id='30000000-0000-0000-0000-000000000001' then 'absent_unexcused' else 'present' end,'homework_status',case when student_id='30000000-0000-0000-0000-000000000001' then 'missing' else 'done' end,'old_lesson_status','passed','quick_score',case when student_id='30000000-0000-0000-0000-000000000001' then 4 else null end,'needs_attention',student_id='30000000-0000-0000-0000-000000000005','attention_reasons',case when student_id='30000000-0000-0000-0000-000000000005' then '["focus"]'::jsonb else '[]'::jsonb end,'teacher_note','private-note-marker'))) from public.session_student_records)::text,true);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',1,jsonb_set('''||current_setting('p2.data')||'''::jsonb,''{records,0,quick_score}'',''11''::jsonb),true)','23514');
select pg_temp.assert_true((select count(*)=0 from public.student_events),'Invalid completion creates no events');
select pg_temp.assert_true((select count(*)=0 from public.tasks),'Invalid completion creates no tasks');
select pg_temp.assert_true((select status='in_progress' and version=1 from public.class_sessions),'Invalid completion rolls back status');
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',null,'''||current_setting('p2.data')||'''::jsonb,false)','40001');
select public.save_session_checkout(current_setting('p2.session')::uuid,1,current_setting('p2.data')::jsonb,false);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',1,'''||current_setting('p2.data')||'''::jsonb,false)','40001');
reset role;
delete from public.cskh_student_assignments where student_id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.save_session_checkout(current_setting('p2.session')::uuid,2,current_setting('p2.data')::jsonb,true);
reset role;
select pg_temp.assert_true((select count(*)=5 from public.tasks),'All deterministic task rules');
select pg_temp.assert_true((select count(*)=1 from public.tasks where owner_id is null),'Missing owner keeps unassigned task');
select set_config('p2.events',(select count(*)::text from public.student_events),true);
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.save_session_checkout(current_setting('p2.session')::uuid,2,current_setting('p2.data')::jsonb,true);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',3,'''||current_setting('p2.data')||'''::jsonb,false)');
select pg_temp.assert_true((select count(*)=1 from public.tasks),'Teacher sees only own review task');
reset role;
select pg_temp.assert_true((select count(*)=5 from public.tasks),'Replay creates no duplicate tasks');
select pg_temp.assert_true((select count(*)::text=current_setting('p2.events') from public.student_events),'Replay creates no duplicate events');
update public.profiles set active=false where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',2,'''||current_setting('p2.data')||'''::jsonb,true)','42501');
reset role;
update public.profiles set active=true where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.second',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '50 minutes',now()-interval '10 minutes','Repeat homework')::text,true);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.second')::uuid);
select public.save_session_checkout(current_setting('p2.second')::uuid,1,current_setting('p2.data')::jsonb,true);
select pg_temp.assert_true(public.student_pulse('30000000-0000-0000-0000-000000000001')->>'color'='red','Pulse explains repeated missing/low score');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.tasks where type='homework_followup' and priority='high'),'Repeated missing raises single active task');
select pg_temp.assert_true((select count(*)=5 from public.tasks),'Cross-session deduplication');
insert into public.session_attachments(session_id,uploaded_by,storage_path,mime_type,size_bytes) values(current_setting('p2.session')::uuid,'10000000-0000-0000-0000-000000000002',current_setting('p2.session')||'/51000000-0000-0000-0000-000000000001.png','image/png',100);
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=3 from public.tasks),'CSKH gets only owned tasks');
select pg_temp.assert_true((select count(*)=0 from public.record_notes),'CSKH cannot read private notes');
select pg_temp.assert_true((select count(*)=0 from public.session_attachments),'CSKH cannot read attachments');
select pg_temp.reject('update public.session_student_records set quick_score=10','42501');
select pg_temp.assert_true(not exists(select 1 from public.student_events where summary like '%private-note-marker%'),'Timeline does not expose private notes');
select public.update_task(id,version,'done','Followed up',null,null) from public.tasks where type='homework_followup';
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000006';
select pg_temp.assert_true((select count(*)=0 from public.session_attachments),'Media cannot see private attachments');
select pg_temp.assert_true((select count(*)=0 from public.student_events),'Media cannot see timeline');
select pg_temp.reject('select public.student_pulse(''30000000-0000-0000-0000-000000000001'')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((select count(*)=1 from public.session_attachments),'Admin reads attachments');
select pg_temp.assert_true((public.command_summary()->>'unassigned')::int=1,'Admin sees missing owner exception');
rollback;
select 'Teaching RPC/rules/pulse/RLS/atomicity/idempotency tests PASS' as result;
